// renameReferences carries a renamed key over to every field of another table that refers
// to it (Rename). References from company tables are updated in this company — in
// every company when this table is global. Runs on the record's executor, so inside the
// caller's transaction.
func (t *TaxBusinessPostingGroup) renameReferences(field string, oldValue, newValue interface{}) error {
	type reference struct {
		table      string
		global     bool
		column     string
		condColumn string // a conditional relation: only rows whose condColumn = condValue
		condValue  int
	}
	references := map[string][]reference{
		"code": {{"Customer", false, "tax_bus_posting_group", "", 0}, {"FA_Ledger_Entry", false, "tax_bus_posting_group", "", 0}, {"Finance_Charge_Memo_Header", false, "tax_bus_posting_group", "", 0}, {"Gen_Business_Posting_Group", false, "def_tax_bus_posting_group", "", 0}, {"Gen_Jnl_Allocation", false, "tax_bus_posting_group", "", 0}, {"Gen_Journal_Line", false, "tax_bus_posting_group", "", 0}, {"Gen_Journal_Line", false, "bal_tax_bus_posting_group", "", 0}, {"G_L_Account", false, "tax_bus_posting_group", "", 0}, {"G_L_Entry", false, "tax_bus_posting_group", "", 0}, {"Issued_Fin_Charge_Memo_Header", false, "tax_bus_posting_group", "", 0}, {"Issued_Reminder_Header", false, "tax_bus_posting_group", "", 0}, {"Item", false, "tax_bus_posting_gr_price", "", 0}, {"Item_Price", false, "tax_bus_posting_gr_price", "", 0}, {"Item_Price_Change", false, "tax_bus_posting_gr_price", "", 0}, {"Maintenance_Ledger_Entry", false, "tax_bus_posting_group", "", 0}, {"Price_Group", false, "tax_bus_posting_gr_price", "", 0}, {"Purch_Cr_Memo_Hdr", false, "tax_bus_posting_group", "", 0}, {"Purch_Cr_Memo_Line", false, "tax_bus_posting_group", "", 0}, {"Purch_Inv_Header", false, "tax_bus_posting_group", "", 0}, {"Purch_Inv_Line", false, "tax_bus_posting_group", "", 0}, {"Purch_Rcpt_Header", false, "tax_bus_posting_group", "", 0}, {"Purch_Rcpt_Line", false, "tax_bus_posting_group", "", 0}, {"Purchase_Header", false, "tax_bus_posting_group", "", 0}, {"Purchase_Line", false, "tax_bus_posting_group", "", 0}, {"Reminder_Header", false, "tax_bus_posting_group", "", 0}, {"Sales_Cr_Memo_Header", false, "tax_bus_posting_group", "", 0}, {"Sales_Cr_Memo_Line", false, "tax_bus_posting_group", "", 0}, {"Sales_Header", false, "tax_bus_posting_group", "", 0}, {"Sales_Invoice_Header", false, "tax_bus_posting_group", "", 0}, {"Sales_Invoice_Line", false, "tax_bus_posting_group", "", 0}, {"Sales_Line", false, "tax_bus_posting_group", "", 0}, {"Sales_Shipment_Header", false, "tax_bus_posting_group", "", 0}, {"Sales_Shipment_Line", false, "tax_bus_posting_group", "", 0}, {"Tax_Entry", false, "tax_bus_posting_group", "", 0}, {"Tax_Posting_Setup", false, "tax_bus_posting_group", "", 0}, {"Tax_Statement_Line", false, "tax_bus_posting_group", "", 0}, {"Vendor", false, "tax_bus_posting_group", "", 0}},
	}
	companies := []string{t.company}
	for _, ref := range references[field] {
		tables := []string{ref.table}
		if !ref.global {
			tables = tables[:0]
			for _, c := range companies {
				tables = append(tables, c+"$"+ref.table)
			}
		}
		for _, tbl := range tables {
			stmt := fmt.Sprintf(`UPDATE "%s" SET %s = ? WHERE %s = ?`, tbl, ref.column, ref.column)
			args := []interface{}{newValue, oldValue}
			if ref.condColumn != "" {
				stmt += fmt.Sprintf(" AND %s = ?", ref.condColumn)
				args = append(args, ref.condValue)
			}
			query := t.convertPlaceholders(stmt, len(args))
			if _, err := t.db.Exec(query, args...); err != nil {
				return fmt.Errorf("%s.%s: %w", tbl, ref.column, err)
			}
		}
	}
	return nil
}

